# ── M1 ──
E(C,'M1-Z01','Il regolamento CLP: classi e categorie di pericolo',[CL("Quale pittogramma?","Seleziona un pericolo, poi il pittogramma corretto.",["GHS02 · fiamma","GHS05 · corrosione","GHS06 · teschio","GHS07 · punto esclamativo","GHS08 · pericolo per la salute","GHS09 · ambiente"],[
 ["Liquido infiammabile, categoria 2",0,"La fiamma indica gas, liquidi e solidi infiammabili."],["Corrosione cutanea, categoria 1",1,"La corrosione vale per pelle, occhi e metalli."],
 ["Tossicità acuta per inalazione, categoria 2",2,"Il teschio indica la tossicità acuta di categoria 1, 2 o 3."],["Irritazione cutanea, categoria 2",3,"Il punto esclamativo indica irritazione e pericoli minori."],
 ["Cancerogenicità, categoria 1B",4,"La sagoma con la stella indica i pericoli gravi a lungo termine."],["Pericoloso per l’ambiente acquatico, cronico 2",5,"Albero e pesce indicano il pericolo per l’ambiente acquatico."],
 ["Sensibilizzazione delle vie respiratorie",4,"È un pericolo grave per la salute."],["Tossicità acuta per ingestione, categoria 4",3,"La categoria 4 usa il punto esclamativo."]],
 "Otto pericoli classificati secondo il CLP. Associa a ciascuno il pittogramma corretto.","Reg. (CE) 1272/2008, Allegato V")])
E(C,'M1-Z02','Le nuove classi di pericolo: interferenti endocrini, PBT e PMT',[CL("Classe vecchia o nuova?","Seleziona una classe di pericolo, poi la colonna.",["Classi introdotte nel 2023","Classi già presenti"],[
 ["Interferenti endocrini per la salute umana",0,"Introdotta dal Reg. delegato (UE) 2023/707."],["Persistenti, mobili e tossiche (PMT)",0,"Nuova classe."],
 ["Persistenti, bioaccumulabili e tossiche (PBT)",0,"Diventa classe di pericolo del CLP con il regolamento del 2023."],["Tossicità per la riproduzione",1,"Era già presente."],
 ["Sensibilizzazione cutanea",1,"Era già presente."],["Interferenti endocrini per l’ambiente",0,"Nuova classe."]],
 "Sei classi di pericolo. Distingui quelle introdotte nel duemilaventitré da quelle già presenti nel CLP.","Reg. delegato (UE) 2023/707")])
E(C,'M1-Z03','La classificazione delle miscele',[ES("Esempio guidato · Classificare una miscela con il metodo di calcolo","Corrosione e irritazione cutanea di un detergente.",[
 ["I componenti","La miscela contiene il 3% di un componente Skin Corr. 1 e l’8% di un componente Skin Irrit. 2.","3% Corr. 1 · 8% Irrit. 2"],
 ["Corrosione","Si classifica Skin Corr. 1 se la somma dei componenti corrosivi è almeno il 5%.","3% < 5% → non corrosiva"],
 ["Irritazione","Si classifica Skin Irrit. 2 se 10 × (corrosivi) + (irritanti) è almeno il 10%.","10 × 3 + 8 = 38% ≥ 10%"],
 ["Il risultato","La miscela è classificata irritante per la pelle, categoria 2.","Skin Irrit. 2 · H315"],
 ["L’etichetta","Pittogramma GHS07, avvertenza «Attenzione».","GHS07 · Attenzione"]],
 "Classifichiamo un detergente con il metodo di calcolo. Contiene il tre per cento di un componente corrosivo e l’otto per cento di un irritante. Per la corrosione servirebbe almeno il cinque per cento di componenti corrosivi: non basta. Per l’irritazione si somma dieci volte la quota dei corrosivi più quella degli irritanti: trenta più otto fa trentotto, oltre la soglia del dieci per cento. La miscela è quindi irritante per la pelle, categoria due, con il punto esclamativo e l’avvertenza «Attenzione».","Reg. (CE) 1272/2008, Allegato I, punto 3.2.3")])
E(C,'M1-Z04','Etichettatura e scheda di dati di sicurezza',[LB("Laboratorio · Etichetta e scheda di uno sgrassante","Un reparto di manutenzione usa un nuovo sgrassante a base di solventi.",[
  ["Pittogrammi","GHS02, GHS07, GHS09"],["Avvertenza","Pericolo"],["Indicazioni H","H225 liquido e vapori facilmente infiammabili; H315 provoca irritazione cutanea; H336 può provocare sonnolenza o vertigini; H411 tossico per gli organismi acquatici con effetti di lunga durata"],["Consigli P","P210 tenere lontano da fonti di calore e scintille; P280 indossare guanti e protezione per gli occhi"],["Uso","pulizia di pezzi meccanici a pennello, in un locale piccolo"]],[
  ("Spiega in parole semplici i pericoli del prodotto per gli addetti.",6,"Prende fuoco molto facilmente e i vapori possono incendiarsi; irrita la pelle; respirare i vapori può dare sonnolenza e vertigini; è dannoso per l’ambiente acquatico e non va disperso negli scarichi.",["Ho spiegato il pericolo di incendio","Ho spiegato gli effetti su pelle e sistema nervoso","Ho indicato il pericolo per l’ambiente"]),
  ("Quali sezioni della scheda consulti e per che cosa?",6,"Sezione 7 per lo stoccaggio e le incompatibilità; sezione 8 per i valori limite, i controlli tecnici e i DPI, come il tipo di guanto e di filtro; sezione 5 e 6 per incendio e sversamenti; sezione 13 per lo smaltimento; sezione 4 per il primo soccorso.",["Ho indicato le sezioni 7 e 8","Ho indicato le sezioni per le emergenze","Ho indicato la sezione 13"]),
  ("Quali misure proponi per l’uso nel locale piccolo?",7,"Valutare la sostituzione con un prodotto a base acquosa; se non possibile, aspirazione localizzata o banco aspirato e ventilazione; quantità minime al posto di lavoro in contenitori chiusi ed etichettati; nessuna fonte di innesco; guanti adatti secondo la sezione 8 e occhiali; formazione degli addetti.",["Ho considerato la sostituzione","Ho previsto ventilazione e controllo delle fonti di innesco","Ho indicato i DPI secondo la sezione 8"])],
 "Nel laboratorio interpreti l’etichetta di uno sgrassante e la sua scheda di dati di sicurezza. Spiega i pericoli agli addetti, individua le sezioni da consultare e proponi le misure per l’uso in un locale piccolo, poi confronta ogni risposta con la soluzione di riferimento.","Reg. (CE) 1272/2008 · Reg. (UE) 2020/878")])
E(C,'M1-Z05','Esempio applicativo: leggere la scheda di dati di sicurezza',[LB("Laboratorio · La scheda che non convince","Controlli la scheda di dati di sicurezza di una vernice ricevuta da un nuovo fornitore.",[
  ["Data di revisione","2017"],["Formato","sezioni conformi al vecchio Allegato II"],["Sezione 3","componenti senza intervalli di concentrazione"],["Sezione 8","«usare DPI adeguati», nessun valore limite e nessun tipo di guanto"],["Lingua","in parte in inglese"]],[
  ("Elenca le carenze della scheda.",6,"Scheda datata e non aggiornata al Reg. (UE) 2020/878; composizione incompleta; sezione 8 generica, senza valori limite né indicazioni concrete su guanti e protezione respiratoria; scheda non interamente in italiano.",["Ho rilevato la data e il formato","Ho rilevato la sezione 3 incompleta","Ho rilevato la sezione 8 generica e la lingua"]),
  ("Che cosa chiedi al fornitore e perché?",5,"Una scheda aggiornata, conforme all’Allegato II modificato, in lingua italiana, con composizione e sezione 8 complete: il fornitore è obbligato a fornirla e l’utilizzatore ne ha bisogno per valutare il rischio.",["Ho chiesto la scheda aggiornata in italiano","Ho motivato con l’obbligo del fornitore"]),
  ("Nel frattempo come gestisci il prodotto?",6,"Si sospende l’introduzione o la si limita con misure prudenziali: uso in cabina aspirata, DPI scelti sui componenti noti, quantità minime; si registra la richiesta e si aggiorna la valutazione appena arriva la scheda corretta.",["Ho previsto misure prudenziali","Ho previsto la registrazione della richiesta","Ho previsto l’aggiornamento della valutazione"])],
 "Il laboratorio ti chiede di valutare la qualità di una scheda di dati di sicurezza. Individua le carenze, decidi che cosa chiedere al fornitore e come gestire il prodotto nel frattempo, poi confronta ogni risposta con la soluzione di riferimento.","Art. 31 Reg. (CE) 1907/2006 · Reg. (UE) 2020/878")])
E(C,'M1-Z06','Il regolamento REACH e gli obblighi dell’utilizzatore',[CL("A chi spetta l’obbligo?","Seleziona un obbligo REACH, poi il soggetto tenuto.",["Fabbricante o importatore","Utilizzatore a valle","Fornitore di articoli"],[
 ["Registrare la sostanza prodotta oltre 1 t/anno",0,"La registrazione spetta a chi fabbrica o importa."],["Verificare che il proprio uso rientri negli scenari di esposizione",1,"È l’obbligo tipico dell’utilizzatore a valle."],
 ["Comunicare la presenza di SVHC oltre lo 0,1% negli articoli",2,"Art. 33 del REACH."],["Applicare le misure di gestione del rischio della SDS estesa",1,"L’utilizzatore attua le misure indicate."],
 ["Preparare il fascicolo e la relazione sulla sicurezza chimica",0,"Spetta al dichiarante, oltre 10 t/anno."],["Rispondere al consumatore entro 45 giorni",2,"Art. 33, comma 2."]],
 "Sei obblighi del REACH. Individua il soggetto a cui spettano.","Reg. (CE) 1907/2006, artt. 6, 14, 33 e 37")])
E(C,'M1-Z07','La restrizione sui diisocianati: formazione obbligatoria',[SC("La schiuma poliuretanica in cantiere","Un’impresa di serramenti usa schiume poliuretaniche monocomponenti con diisocianati oltre lo 0,1% per sigillare gli infissi.",[
 ("Che cosa serve prima dell’uso professionale?",[["Nulla di particolare",False,"La restrizione della voce 74 impone una formazione specifica."],["La formazione specifica sull’uso sicuro dei diisocianati, completata con esito positivo",True,"Corretto: è obbligatoria dal 24 agosto 2023."],["Solo il certificato medico",False,"Non sostituisce la formazione."]]),
 ("Ogni quanto si rinnova la formazione?",[["Almeno ogni cinque anni",True,"Corretto."],["Ogni anno",False,"La periodicità minima è quinquennale."],["Mai",False,"Va rinnovata."]]),
 ("Un nuovo addetto non ha ancora la formazione. Che cosa fai?",[["Lo fai lavorare affiancato",False,"L’uso professionale richiede la formazione completata."],["Non lo adibisci all’uso finché non completa la formazione, e lo documenti",True,"Corretto: l’impresa deve poter dimostrare la formazione."],["Gli dai un DPI in più",False,"Non sostituisce la formazione."]])],
 "Formazione specifica prima dell’uso, rinnovo almeno quinquennale e documentazione: la restrizione sui diisocianati si applica a ogni utilizzatore professionale.","Schiume con diisocianati usate in cantiere. Verifica gli obblighi.","Reg. (CE) 1907/2006, Allegato XVII, voce 74")])
E(C,'M1-Z08','Articoli con SVHC: art. 33 e banca dati SCIP',[SC("La domanda del cliente","Un cliente privato chiede a un’impresa che vende cavi elettrici se contengono sostanze estremamente preoccupanti. Un plastificante dell’elenco delle candidate è presente allo 0,3% in peso.",[
 ("L’impresa deve rispondere?",[["Sì: gratuitamente, entro 45 giorni, almeno con il nome della sostanza",True,"Corretto: art. 33, comma 2."],["No, è un segreto commerciale",False,"L’informazione è dovuta."],["Solo se il cliente è un’impresa",False,"Il diritto vale anche per il consumatore."]]),
 ("E verso i clienti professionali?",[["Deve informarli già alla fornitura, con le informazioni per l’uso sicuro",True,"Corretto: art. 33, comma 1."],["Solo su richiesta",False,"Per i destinatari professionali l’obbligo è automatico."],["Mai",False,"È un obbligo."]]),
 ("Quale altro adempimento riguarda il fornitore di articoli con SVHC oltre lo 0,1%?",[["La notifica alla banca dati SCIP dell’ECHA",True,"Corretto: prevista dalla direttiva quadro sui rifiuti."],["La registrazione della sostanza",False,"Riguarda fabbricanti e importatori."],["Nessuno",False,"C’è la notifica SCIP."]])],
 "Informare i clienti professionali, rispondere al consumatore entro 45 giorni e notificare in SCIP: sono gli obblighi di chi fornisce articoli con sostanze estremamente preoccupanti.","Un cliente chiede delle sostanze nei cavi. Rispondi correttamente.","Art. 33 Reg. (CE) 1907/2006 · art. 9 Dir. 2008/98/CE")])
E(C,'M1-Z09','Scenari di esposizione e SDS estesa',[LB("Laboratorio · L’uso rientra nello scenario?","Confronti lo scenario di esposizione di un solvente con l’uso reale in reparto.",[
  ["Scenario","applicazione a pennello; aspirazione localizzata; durata massima 4 ore al giorno; guanti in gomma nitrilica"],["Uso reale","applicazione a spruzzo, senza aspirazione, per circa 6 ore al giorno"],["DPI","guanti in lattice"]],[
  ("L’uso è coperto dallo scenario? Motiva.",6,"No: cambia la tecnica, da pennello a spruzzo, manca l’aspirazione, la durata supera le 4 ore e i guanti non sono quelli indicati. Le condizioni operative e le misure di gestione del rischio non corrispondono.",["Ho confrontato tecnica e durata","Ho rilevato l’assenza di aspirazione","Ho rilevato i guanti non conformi"]),
  ("Quali opzioni ha l’utilizzatore a valle?",7,"Adeguare l’uso alle condizioni dello scenario, ad esempio introducendo aspirazione, limitando la durata e usando i guanti indicati; oppure chiedere al fornitore di includere l’uso; oppure redigere una propria relazione sulla sicurezza chimica e notificarla all’ECHA, salvo esenzioni.",["Ho indicato l’adeguamento","Ho indicato la richiesta al fornitore","Ho indicato la relazione dell’utilizzatore a valle"]),
  ("Che cosa documenti nella valutazione dei rischi?",5,"Il confronto con lo scenario, l’opzione scelta, le misure adottate e i tempi; l’aggiornamento della scheda di reparto e la formazione degli addetti.",["Ho documentato confronto e scelta","Ho previsto la scheda di reparto e la formazione"])],
 "Nel laboratorio confronti lo scenario di esposizione di un solvente con l’uso reale. Valuta se l’uso è coperto, individua le opzioni dell’utilizzatore a valle e indica che cosa documentare, poi confronta ogni risposta con la soluzione di riferimento.","Art. 37 Reg. (CE) 1907/2006")])
E(C,'M1-Z10','Esercitazione · Il travaso nella bottiglia',[AP("Gli agenti chimici della tua azienda","Fai un primo inventario degli agenti chimici.",["Ho l’elenco dei prodotti in uso","Ogni prodotto ha la scheda aggiornata","I contenitori sono tutti etichettati","Ci sono travasi in contenitori anonimi","Esistono schede di reparto per gli addetti","Ci sono prodotti con diisocianati","Ci sono agenti cancerogeni o mutageni"],"Il prodotto più critico e perché","Es.: diluente nitro usato a spruzzo senza aspirazione",
  "Fai un primo inventario degli agenti chimici della tua azienda e indica il prodotto più critico.",3),
 VF("Ripasso · Classificazione e informazione",[["Un pittogramma GHS07 può indicare la tossicità acuta di categoria 4.",True,"Vero: la categoria 4 usa il punto esclamativo."],["La scheda di dati di sicurezza si può fornire solo in inglese.",False,"Falso: va fornita nella lingua dello Stato membro."],["Il codice UFI ha 16 caratteri.",True,"Vero."],["L’utilizzatore a valle deve registrare le sostanze che acquista.",False,"Falso: la registrazione spetta a fabbricanti e importatori."]],"Ripasso: quattro affermazioni su classificazione e informazione.","Reg. (CE) 1272/2008 · Reg. (CE) 1907/2006")])
# ── M2 ──
E(C,'M2-Z01','Rischio «basso per la sicurezza» e «irrilevante per la salute»',[SC("Il laboratorio di controllo qualità","In un laboratorio di controllo qualità si usano piccole quantità di acetone e acidi diluiti per pochi minuti al giorno, sotto cappa.",[
 ("Il rischio può essere «irrilevante per la salute»?",[["Sì, se la valutazione su quantità, frequenza, proprietà e condizioni d’uso lo dimostra e viene documentata",True,"Corretto: la conclusione va motivata nel documento."],["Sì, sempre, perché sono quantità piccole",False,"La conclusione deve essere motivata."],["No, mai in un laboratorio",False,"Dipende dalla valutazione."]]),
 ("Se il rischio è irrilevante, che cosa si applica comunque?",[["Le misure generali dell’art. 224, comma 1",True,"Corretto: valgono sempre."],["Nessuna misura",False,"Le misure generali si applicano sempre."],["La sorveglianza sanitaria",False,"Non è obbligatoria in caso di rischio irrilevante."]]),
 ("Il laboratorio introduce un solvente classificato tossico per la riproduzione. Che cosa cambia?",[["Nulla",False,"Cambia l’ambito di applicazione."],["Si applica il Capo II: sostituzione, sistema chiuso o esposizione al livello più basso possibile, registro degli esposti",True,"Corretto: dopo il D.lgs. 135/2024 i reprotossici 1A e 1B rientrano nel Capo II."],["Basta un guanto in più",False,"Non basta."]])],
 "Il rischio irrilevante va dimostrato e documentato, le misure generali valgono sempre, e un agente reprotossico porta la valutazione nel Capo II.","Un laboratorio con piccole quantità di prodotti. Valuta il livello di rischio.","Artt. 223-224 e 234 D.lgs. 81/2008")])
E(C,'M2-Z02','Esempio applicativo: da ppm a mg/m³',[LB("Laboratorio · L’esposizione media ponderata di un verniciatore","Calcola l’esposizione a toluene di un verniciatore in una giornata tipo.",[
  ["Fase 1","2 ore di verniciatura in cabina: 150 mg/m³"],["Fase 2","4 ore di preparazione dei pezzi: 60 mg/m³"],["Fase 3","2 ore di imballaggio, nessuna esposizione"],["Valore limite","toluene 192 mg/m³ (50 ppm) su 8 ore"],["Massa molare","92,14 g/mol"]],[
  ("Calcola la concentrazione media ponderata sulle 8 ore.",6,"(150 × 2 + 60 × 4 + 0 × 2) / 8 = (300 + 240) / 8 = 67,5 mg/m³.",["Ho moltiplicato concentrazioni e durate","Ho diviso per 8 ore","Ho ottenuto 67,5 mg/m³"]),
  ("Confronta il risultato con il valore limite e interpretalo.",6,"67,5 / 192 ≈ 0,35: l’esposizione è circa il 35% del valore limite. È inferiore al limite, ma non trascurabile: la conformità va verificata con una strategia di misura secondo la UNI EN 689 e le misure vanno mantenute.",["Ho calcolato il rapporto con il limite","Ho evitato di concludere con una sola stima","Ho richiamato la UNI EN 689"]),
  ("Converti il valore in ppm.",5,"ppm = mg/m³ × 24,06 / M = 67,5 × 24,06 / 92,14 ≈ 17,6 ppm.",["Ho usato la formula inversa","Ho ottenuto circa 17,6 ppm"])],
 "Nel laboratorio calcoli l’esposizione media ponderata di un verniciatore esposto a toluene in tre fasi della giornata. Calcola il valore sulle otto ore, confrontalo con il limite e convertilo in ppm, poi confronta ogni risposta con la soluzione di riferimento.","Allegato XXXVIII D.lgs. 81/2008 · UNI EN 689")])
E(C,'M2-Z03','La UNI EN 689: strategia di misura',[CL("Quale allegato del D.lgs. 81/2008?","Seleziona un riferimento, poi l’allegato.",["XXXVIII · valori limite professionali","XXXIX · valori limite biologici","XLII · lavorazioni cancerogene","XLIII · valori limite di cancerogeni e mutageni"],[
 ["Valore limite del toluene",0,"Allegato XXXVIII."],["Piombo nel sangue",1,"Allegato XXXIX."],
 ["Lavori che espongono a polvere di silice cristallina respirabile",2,"Allegato XLII."],["Valore limite del benzene",3,"Allegato XLIII."],
 ["Lavori che espongono a polveri di legno duro",2,"Allegato XLII."],["Valore limite dell’acetone",0,"Allegato XXXVIII."]],
 "Sei riferimenti normativi. Individua l’allegato del Titolo IX che li contiene.","D.lgs. 81/2008, Titolo IX")])
E(C,'M2-Z04','Il test statistico e la rivalutazione periodica',[ES("Esempio guidato · Ogni quanto rimisurare?","La rivalutazione periodica secondo la UNI EN 689.",[
 ["Il risultato","Il test statistico conclude per la conformità del gruppo di esposizione similare.","Conformità"],
 ["La media geometrica","La media geometrica delle misure è 0,3 volte il valore limite.","MG = 0,3 × VL"],
 ["L’intervallo","Con MG tra 0,25 e 0,5 VL la norma suggerisce una nuova misura entro 18 mesi.","18 mesi"],
 ["I confronti","Sotto 0,1 VL: 36 mesi; tra 0,1 e 0,25: 24 mesi; da 0,5 VL in su: 12 mesi.","36 · 24 · 18 · 12 mesi"],
 ["Le eccezioni","Ogni modifica di processo, prodotto o misure richiede una nuova valutazione, indipendentemente dalla scadenza.","Modifiche → nuova valutazione"]],
 "Vediamo la rivalutazione periodica. Il gruppo è conforme e la media geometrica delle misure vale zero virgola tre volte il valore limite. In questa fascia la norma suggerisce di rimisurare entro diciotto mesi; sotto un decimo del limite si arriva a trentasei mesi, mentre da metà del limite in su si scende a dodici. Qualsiasi modifica del processo richiede comunque una nuova valutazione.","UNI EN 689:2019, Allegato I")])
E(C,'M2-Z05','Esempio applicativo: il test preliminare della UNI EN 689',[LB("Laboratorio · Il test preliminare dei verniciatori","Valuti le misure di un gruppo di esposizione similare di tre verniciatori.",[
  ["Agente","toluene, valore limite 192 mg/m³"],["Misure personali su 8 ore","12 mg/m³ · 15 mg/m³ · 21 mg/m³"],["Gruppo","3 verniciatori con stessi compiti, cabina e prodotti"]],[
  ("Applica il test preliminare con tre misure.",6,"Il 10% del valore limite è 19,2 mg/m³. Una misura, 21 mg/m³, supera questa soglia: il test preliminare non dimostra la conformità. Nessuna misura supera il valore limite, quindi non c’è non conformità.",["Ho calcolato il 10% del limite","Ho confrontato le tre misure","Ho distinto mancata conformità e non conformità"]),
  ("Che cosa fai ora?",6,"Si passa al test statistico raccogliendo almeno sei misure sul gruppo, si verifica la distribuzione lognormale e si confronta il limite di confidenza superiore con il valore limite. Nel frattempo si mantengono le misure di prevenzione.",["Ho indicato almeno sei misure","Ho richiamato la verifica statistica","Ho previsto il mantenimento delle misure"]),
  ("Il gruppo è davvero omogeneo? Che cosa controlli?",5,"Che i tre lavoratori svolgano compiti, durate e processi analoghi e che una misura non sia anomala per una condizione particolare; se un lavoratore ha un profilo diverso, il gruppo va ridefinito.",["Ho verificato compiti e durate","Ho considerato le misure anomale","Ho previsto la ridefinizione del gruppo"])],
 "Nel laboratorio applichi il test preliminare della UNI EN 689 a tre misure di toluene. Verifica il risultato, decidi i passi successivi e controlla l’omogeneità del gruppo, poi confronta ogni risposta con la soluzione di riferimento.","UNI EN 689:2019")])
E(C,'M2-Z06','Cancerogeni, mutageni e reprotossici: il Capo II dopo il D.lgs. 135/2024',[CL("Capo I o Capo II?","Seleziona un agente, poi il capo del Titolo IX che si applica.",["Capo I · agenti chimici","Capo II · cancerogeni, mutageni, reprotossici"],[
 ["Toluene usato come diluente",0,"Non è classificato cancerogeno né reprotossico di categoria 1."],["Benzene",1,"Cancerogeno di categoria 1A."],
 ["Formaldeide",1,"Cancerogena di categoria 1B."],["Polvere di silice cristallina respirabile da lavorazioni",1,"Lavorazione dell’Allegato XLII."],
 ["Acetone",0,"Agente chimico del Capo I."],["Composti del piombo tossici per la riproduzione",1,"Dopo il D.lgs. 135/2024 i reprotossici 1A e 1B rientrano nel Capo II."],
 ["Idrossido di sodio",0,"Corrosivo: Capo I."],["Polveri di legno duro",1,"Lavorazione dell’Allegato XLII."]],
 "Otto agenti. Indica se la valutazione rientra nel Capo I o nel Capo II del Titolo IX.","D.lgs. 81/2008, Titolo IX, Capi I e II")])
E(C,'M2-Z07','Cancerogeni, mutageni e reprotossici: obblighi specifici',[SC("Il registro degli esposti","Un’impresa di galvanica usa un bagno con un sale di nichel classificato cancerogeno di categoria 1A. Non ha mai istituito il registro degli esposti.",[
 ("Che cosa fai per primo?",[["Verifichi se l’agente può essere sostituito o il processo chiuso",True,"Corretto: la sostituzione è l’obbligo prioritario."],["Istituisci il registro e basta",False,"Il registro non sostituisce la riduzione dell’esposizione."],["Nulla, il bagno è sempre stato così",False,"Gli obblighi valgono anche per i processi esistenti."]]),
 ("Chi va iscritto nel registro?",[["I lavoratori per i quali la valutazione ha evidenziato un’esposizione",True,"Corretto: art. 243."],["Tutti i dipendenti",False,"Solo gli esposti."],["Nessuno, se usano i DPI",False,"I DPI non escludono l’esposizione."]]),
 ("Per quanto si conservano registro e cartelle?",[["Almeno 40 anni dalla cessazione dell’esposizione",True,"Corretto."],["5 anni",False,"Il periodo è molto più lungo."],["Fino al licenziamento",False,"Non è così."]])],
 "Sostituire o chiudere il processo, iscrivere gli esposti nel registro, conservare registro e cartelle per almeno quarant’anni: sono gli obblighi specifici per gli agenti cancerogeni.","Un bagno galvanico con un agente cancerogeno. Metti in regola l’impresa.","Artt. 235, 236 e 243 D.lgs. 81/2008")])
E(C,'M2-Z08','Piombo e diisocianati: la Direttiva (UE) 2024/869',[ES("Esempio guidato · Il piombo nel sangue","Confronto con il nuovo valore limite biologico.",[
 ["Il risultato","Il monitoraggio biologico di un addetto alla fusione rileva 22 µg di piombo per 100 ml di sangue.","22 µg/100 ml"],
 ["Il riferimento","Il nuovo valore limite biologico è di 15 µg/100 ml.","22 > 15"],
 ["La lettura","Il valore è superato: l’esposizione non è adeguatamente controllata.","Superamento"],
 ["Le azioni","Il medico competente informa il lavoratore e il datore di lavoro; si rivedono misure tecniche e igieniche, come l’aspirazione e il divieto di mangiare in reparto.","Rivalutazione delle misure"],
 ["La verifica","Nuovo monitoraggio dopo gli interventi per verificarne l’efficacia.","Controllo di efficacia"]],
 "Un addetto alla fusione ha ventidue microgrammi di piombo per cento millilitri di sangue. Il nuovo valore limite biologico è quindici: il valore è superato e l’esposizione non è sotto controllo. Il medico competente informa lavoratore e datore di lavoro, si rivedono aspirazione e misure igieniche, come il divieto di mangiare in reparto, e si ripete il monitoraggio per verificare l’efficacia degli interventi.","Dir. (UE) 2024/869 · Allegato XXXIX D.lgs. 81/2008")])
E(C,'M2-Z09','Esercitazione · Silice cristallina in un laboratorio di marmo',[LB("Laboratorio · Valutare il rischio chimico di una galvanica","Imposta la valutazione del rischio chimico di una piccola galvanica con 8 addetti.",[
  ["Agenti","acido solforico (corrosivo); idrossido di sodio (corrosivo); solfato di nichel (cancerogeno 1A, sensibilizzante); sgrassante con solventi (infiammabile)"],["Processi","sgrassaggio, decapaggio, nichelatura in vasche aperte, risciacqui"],["Presidi","aspirazione a bordo vasca solo sulla nichelatura; guanti generici"]],[
  ("Classifica gli agenti e indica quale capo del Titolo IX si applica a ciascuno.",7,"Acido solforico e idrossido di sodio: agenti chimici pericolosi, Capo I, con rischio di corrosione per contatto e aerosol. Sgrassante: Capo I, con pericolo di incendio e di effetti sul sistema nervoso. Solfato di nichel: cancerogeno 1A, Capo II, con obblighi di sostituzione, sistema chiuso o esposizione minima, e registro degli esposti.",["Ho distinto Capo I e Capo II","Ho considerato sicurezza e salute","Ho indicato il registro per il nichel"],None,120),
  ("Proponi le misure secondo la gerarchia.",8,"Valutare la sostituzione del processo al nichel o la riduzione dei componenti pericolosi; coperture delle vasche e aspirazione a bordo vasca su tutte le vasche che emettono aerosol; automazione delle movimentazioni; separazione dei reparti; procedure di dosaggio con sistemi chiusi; guanti specifici secondo le schede, visiere e grembiuli; docce e lavaocchi; divieto di mangiare e fumare.",["Ho seguito l’ordine della gerarchia","Ho previsto aspirazione e coperture","Ho previsto DPI specifici e presidi di emergenza"],None,150),
  ("Quali obblighi di sorveglianza e registrazione individui?",5,"Sorveglianza sanitaria per gli esposti non irrilevanti; registro degli esposti al nichel e cartelle conservate almeno 40 anni; misure ambientali e personali secondo la UNI EN 689; informazione e formazione specifiche.",["Ho indicato la sorveglianza sanitaria","Ho indicato registro e conservazione","Ho previsto misure e formazione"])],
 "Nel laboratorio imposti la valutazione del rischio chimico di una piccola galvanica. Classifica gli agenti, proponi le misure secondo la gerarchia e individua gli obblighi di sorveglianza e registrazione, poi confronta ogni risposta con la soluzione di riferimento.","D.lgs. 81/2008, Titolo IX"),
 VF("Ripasso · Valutazione ed esposizione",[["Con tre misure tutte inferiori al 10% del valore limite il test preliminare dimostra la conformità.",True,"Vero: UNI EN 689."],["La media ponderata si calcola dividendo per le ore effettive di esposizione.",False,"Falso: si riferisce alle 8 ore."],["I reprotossici di categoria 1A e 1B rientrano nel Capo II.",True,"Vero: dopo il D.lgs. 135/2024."],["Il rischio irrilevante per la salute esclude anche le misure generali.",False,"Falso: le misure generali si applicano sempre."]],"Ripasso: quattro affermazioni su valutazione ed esposizione.","D.lgs. 81/2008, Titolo IX · UNI EN 689")])
# ── M3 ──
E(C,'M3-Z01','La gerarchia delle misure (art. 225)',[CL("Quale livello della gerarchia?","Seleziona una misura, poi il livello della gerarchia.",["Sostituzione","Misura tecnica","Protezione collettiva","Misura organizzativa","DPI"],[
 ["Vernice a base acquosa al posto di quella a solvente",0,"Elimina o riduce il pericolo alla fonte."],["Travaso in circuito chiuso con pompa",1,"È un controllo tecnico."],
 ["Ventilazione generale del reparto",2,"Protegge tutti i presenti."],["Riduzione del numero di addetti presenti durante la miscelazione",3,"È organizzativa."],
 ["Semimaschera con filtro A2",4,"È l’ultima barriera."],["Aspirazione localizzata sulla pesatura",1,"Capta l’inquinante alla fonte."],
 ["Turnazione per ridurre la durata dell’esposizione",3,"È organizzativa."],["Detergente non classificato al posto di uno corrosivo",0,"È una sostituzione."]],
 "Otto misure contro il rischio chimico. Collocale nella gerarchia, dalla sostituzione ai dispositivi di protezione individuale.","Art. 225 D.lgs. 81/2008")])
E(C,'M3-Z02','L’aspirazione localizzata',[SC("La cappa che non aspira","Gli addetti alla miscelazione lamentano odore di solvente nonostante la cappa. La cappa è a 80 cm dal punto di miscelazione e il filtro non viene cambiato da due anni.",[
 ("Qual è il problema principale?",[["La distanza della cappa dalla sorgente e il filtro intasato riducono la velocità di cattura",True,"Corretto: l’efficacia cala rapidamente con la distanza e con le perdite di carico."],["Gli addetti sono troppo sensibili",False,"L’odore segnala una captazione insufficiente."],["Serve solo profumare l’ambiente",False,"Non elimina l’esposizione."]]),
 ("Che cosa fai?",[["Avvicini la cappa alla sorgente, la chiudi parzialmente e sostituisci il filtro",True,"Corretto: cappe vicine e semichiuse sono più efficaci."],["Aumenti solo la ventilazione generale",False,"Diluisce ma non capta alla fonte."],["Dai mascherine e lasci tutto com’è",False,"I DPI vengono dopo le misure tecniche."]]),
 ("Come verifichi che funzioni?",[["Misurando la velocità di cattura e programmando verifiche periodiche e manutenzione",True,"Corretto: le prestazioni vanno verificate nel tempo."],["Chiedendo se c’è ancora odore",False,"Non è una verifica affidabile."],["Non serve verificarla",False,"Le prestazioni vanno controllate."]])],
 "Cappa vicina alla sorgente, preferibilmente chiusa o semichiusa, filtri mantenuti e prestazioni misurate: così l’aspirazione localizzata protegge davvero.","Un’aspirazione che non funziona bene. Trova la causa e intervieni.","Art. 225 D.lgs. 81/2008")])
E(C,'M3-Z03','Filtri per le vie respiratorie: tipi e colori',[ES("Esempio guidato · Scegliere il filtro per la verniciatura a spruzzo","Dal contaminante al filtro.",[
 ["I contaminanti","Vapori di toluene e xilene, punto di ebollizione superiore a 65 °C, e nebbie di vernice.","Vapori organici + particelle"],
 ["Il tipo per i vapori","Tipo A, colore marrone.","Filtro A"],
 ["Il filtro per le particelle","Le nebbie di vernice richiedono un filtro antiparticolato, ad esempio P2.","Filtro P2"],
 ["Il filtro combinato","Si usa un filtro combinato A2P2 su semimaschera o maschera intera.","A2P2"],
 ["L’uso","Prova di tenuta, sostituzione dei filtri secondo le istruzioni del fabbricante e conservazione in contenitore chiuso.","Tenuta e sostituzione"]],
 "Scegliamo il filtro per la verniciatura a spruzzo. Ci sono vapori di toluene e xilene, che bollono sopra i sessantacinque gradi, e nebbie di vernice. Per i vapori serve il tipo A, marrone; per le nebbie un filtro antiparticolato, ad esempio P due. Si usa quindi un filtro combinato A due P due, con prova di tenuta e sostituzione secondo le istruzioni del fabbricante.","UNI EN 14387 · UNI EN 529")])
E(C,'M3-Z04','Esempio applicativo: il DVR di una falegnameria con 6 addetti',[LB("Laboratorio · La scheda di rischio del verniciatore","Completa la scheda di valutazione del rischio chimico per il verniciatore della falegnameria.",[
  ["Prodotti","fondo e finitura poliuretanici bicomponenti con diisocianati; diluente a base di acetato di butile e xilene"],["Modalità","spruzzo in cabina con velo d’acqua, 3 ore al giorno"],["Altre esposizioni","polveri di legno duro dalla levigatura, 2 ore al giorno"],["Presidi","cabina; semimaschera con filtro A2P2; guanti in lattice"]],[
  ("Individua gli agenti, i pericoli e il capo del Titolo IX applicabile.",7,"Diisocianati: sensibilizzanti respiratori e cutanei, Capo I con restrizione REACH e formazione obbligatoria. Solventi: infiammabili ed effetti sul sistema nervoso, Capo I. Polveri di legno duro: lavorazione dell’Allegato XLII, Capo II, con valore limite dell’Allegato XLIII.",["Ho individuato i diisocianati come sensibilizzanti","Ho individuato le polveri di legno duro nel Capo II","Ho considerato l’infiammabilità"],None,120),
  ("Valuta l’adeguatezza dei presidi e proponi miglioramenti.",8,"La cabina va verificata nella velocità dell’aria; il filtro A2P2 è adatto ai vapori organici e alle nebbie, ma con i diisocianati occorre valutare un apparecchio a ventilazione assistita o isolante; i guanti in lattice non sono adatti: servono guanti resistenti ai prodotti secondo la scheda, ad esempio in nitrile o butile; per la levigatura aspirazione localizzata sulle macchine.",["Ho criticato i guanti in lattice","Ho valutato la protezione respiratoria con i diisocianati","Ho previsto aspirazione sulla levigatura"],None,150),
  ("Quali obblighi di sorveglianza e formazione aggiungi?",5,"Sorveglianza sanitaria per sensibilizzanti e polveri di legno; iscrizione nel registro degli esposti per le polveri di legno duro; formazione specifica sui diisocianati con rinnovo almeno quinquennale; formazione sull’uso dei DPI con addestramento.",["Ho previsto sorveglianza e registro","Ho previsto la formazione sui diisocianati","Ho previsto l’addestramento ai DPI"])],
 "Il laboratorio ti chiede di completare la scheda di rischio chimico del verniciatore di una falegnameria. Individua agenti e pericoli, valuta i presidi e proponi miglioramenti, poi indica sorveglianza e formazione. Confronta ogni risposta con la soluzione di riferimento.","D.lgs. 81/2008, Titolo IX · Reg. (CE) 1907/2006, Allegato XVII, voce 74")])
E(C,'M3-Z05','Emergenze, sorveglianza sanitaria e informazione',[LB("Laboratorio · Lo sversamento in magazzino","In magazzino un carrellista fora un fusto da 200 litri di solvente facilmente infiammabile: il liquido si sparge sul pavimento.",[
  ["Prodotto","H225, H336, H411"],["Luogo","magazzino chiuso, vicino a una caricabatterie dei carrelli"],["Presenti","due addetti; kit di assorbimento in reparto"]],[
  ("Quali azioni immediate?",6,"Dare l’allarme, allontanare le persone non necessarie, eliminare le fonti di innesco, come la ricarica dei carrelli, senza azionare interruttori nella zona dei vapori se non previsto dalla procedura; ventilare; contenere lo sversamento con barriere per evitare che raggiunga tombini e scarichi.",["Ho previsto allarme e allontanamento","Ho eliminato le fonti di innesco","Ho previsto il contenimento lontano dagli scarichi"]),
  ("Chi interviene, con quali DPI e materiali?",6,"Gli addetti formati alle emergenze, con protezione respiratoria adeguata o, se la concentrazione è elevata, apparecchi isolanti; guanti resistenti al solvente; materiale assorbente non combustibile; utensili antiscintilla; contenitori per i residui.",["Ho limitato l’intervento agli addetti formati","Ho indicato DPI adeguati","Ho indicato materiali e attrezzi antiscintilla"]),
  ("Che cosa si fa dopo l’emergenza?",5,"Il materiale assorbito è un rifiuto pericoloso da classificare e gestire; si analizzano le cause, ad esempio la viabilità dei carrelli e la protezione dei fusti; si aggiornano procedure e valutazione dei rischi; si informano e si formano gli addetti.",["Ho gestito i residui come rifiuto pericoloso","Ho previsto l’analisi delle cause","Ho previsto l’aggiornamento di procedure e valutazione"])],
 "Il laboratorio simula lo sversamento di un solvente infiammabile in magazzino. Indica le azioni immediate, chi interviene con quali dispositivi e che cosa fare dopo l’emergenza, poi confronta ogni risposta con la soluzione di riferimento.","Art. 226 D.lgs. 81/2008")])
E(C,'M3-Z06','Le nuove edizioni delle norme CEI EN IEC 60079',[CL("Quale zona?","Seleziona una situazione, poi la zona di pericolo per gas e vapori.",["Zona 0","Zona 1","Zona 2"],[
 ["Interno di un serbatoio di solvente, sopra il liquido",0,"Atmosfera esplosiva presente continuamente o per lunghi periodi."],["Intorno a una bocca di riempimento aperta durante i travasi",1,"Atmosfera esplosiva probabile durante il normale funzionamento."],
 ["Intorno a flange e valvole in buono stato",2,"Atmosfera esplosiva improbabile e, se si forma, di breve durata."],["Interno di una cabina di verniciatura durante la spruzzatura",1,"Probabile durante il normale funzionamento."],
 ["Locale pompe ben ventilato, con perdite solo in caso di guasto",2,"Formazione solo in caso di anomalia, di breve durata."],["Spazio di testa di un fusto aperto di solvente",0,"Presenza continua."]],
 "Sei situazioni con gas e vapori infiammabili. Assegna la zona di pericolo secondo la classificazione dei luoghi.","Allegato XLIX D.lgs. 81/2008 · CEI EN IEC 60079-10-1")])
E(C,'M3-Z07','Esercitazione · La sostituzione del solvente',[AP("Il tuo piano di miglioramento per il rischio chimico","Scegli le azioni prioritarie per la tua organizzazione.",["Sostituire un prodotto pericoloso","Installare o migliorare un’aspirazione","Aggiornare le schede di dati di sicurezza","Preparare le schede di reparto","Misurare l’esposizione secondo la UNI EN 689","Rivedere la scelta dei guanti","Classificare le zone ATEX","Esercitare la squadra sugli sversamenti"],"L’azione numero uno, chi la guida ed entro quando","Es.: aspirazione sulla miscelazione, responsabile manutenzione, entro marzo",
  "Scegli le azioni prioritarie contro il rischio chimico nella tua azienda e indica l’azione numero uno, chi la guida ed entro quando.",3)])
E(C,'M1-Z11','Il codice UFI e la notifica ai centri antiveleni',[SC("Il detergente importato","Un’impresa importa dalla Svizzera un detergente classificato corrosivo e lo vende a imprese di pulizia italiane.",[
 ("Chi deve notificare la miscela?",[["L’importatore, prima dell’immissione sul mercato",True,"Corretto: l’obbligo spetta a importatori e utilizzatori a valle che immettono miscele sul mercato."],["Il fabbricante svizzero",False,"Fuori dall’Unione l’obbligo ricade sull’importatore."],["I clienti",False,"Non sono tenuti."]]),
 ("Dove si notifica?",[["Tramite il portale dell’ECHA, nel formato armonizzato dell’Allegato VIII",True,"Corretto."],["Con una e-mail all’ASL",False,"Non è la procedura prevista."],["Non serve, è un uso professionale",False,"Anche le miscele per uso professionale vanno notificate."]]),
 ("Che cosa compare sull’etichetta?",[["Il codice UFI di 16 caratteri",True,"Corretto: collega il prodotto alle informazioni per i centri antiveleni."],["Il numero di telefono dell’importatore al posto del pittogramma",False,"Il pittogramma resta obbligatorio."],["Nulla di nuovo",False,"Serve il codice UFI."]])],
 "Notifica armonizzata tramite ECHA prima dell’immissione e codice UFI in etichetta: così i centri antiveleni possono rispondere rapidamente in caso di esposizione.","Un detergente importato da vendere in Italia. Verifica gli obblighi.","Reg. (CE) 1272/2008, art. 45 e Allegato VIII")])
E(C,'M1-Z12','Il regolamento CLP: classi e categorie di pericolo',[CL("Indicazione di pericolo o consiglio di prudenza?","Seleziona una frase, poi la colonna.",["Indicazione di pericolo (H)","Consiglio di prudenza (P)"],[
 ["Provoca gravi ustioni cutanee e gravi lesioni oculari",0,"Descrive il pericolo: H314."],["Indossare guanti protettivi",1,"È un comportamento da seguire: P280."],
 ["Liquido e vapori facilmente infiammabili",0,"H225."],["Tenere lontano da fonti di calore e scintille",1,"P210."],
 ["Può provocare il cancro",0,"H350."],["In caso di contatto con gli occhi sciacquare accuratamente",1,"P305+P351+P338."]],
 "Sei frasi di un’etichetta. Distingui le indicazioni di pericolo dai consigli di prudenza.","Reg. (CE) 1272/2008, Allegati III e IV")])
E(C,'M2-Z10','La UNI EN 689: strategia di misura',[LB("Laboratorio · La silice nel laboratorio del marmo","Imposti la strategia di misura della silice cristallina respirabile in un laboratorio che taglia e lucida lastre di marmo e quarzo agglomerato.",[
  ["Agente","silice cristallina respirabile, valore limite 0,1 mg/m³ (Allegato XLIII)"],["Mansioni","3 addetti al taglio, 2 alla lucidatura, 1 addetto all’ufficio tecnico"],["Misure precedenti","taglio: 0,012 · 0,018 · 0,025 mg/m³"],["Presidi","taglio ad acqua solo su una macchina; pulizia a secco con scopa"]],[
  ("Definisci i gruppi di esposizione similare e il metodo di campionamento.",6,"Due gruppi distinti: taglio e lucidatura; l’addetto dell’ufficio tecnico va valutato a parte. Campionamento personale della frazione respirabile, con selettore ciclonico, rappresentativo dell’intero turno, con analisi della silice cristallina secondo metodi riconosciuti.",["Ho separato taglio e lucidatura","Ho indicato il campionamento personale della frazione respirabile","Ho considerato la durata del turno"]),
  ("Interpreta le misure del taglio.",6,"Il 10% del valore limite è 0,01 mg/m³: tutte e tre le misure lo superano, quindi il test preliminare non dimostra la conformità; nessuna supera il limite. Si passa al test statistico con almeno sei misure. Trattandosi di un cancerogeno, l’esposizione va comunque ridotta al livello più basso tecnicamente possibile.",["Ho applicato il test preliminare","Ho indicato il test statistico","Ho richiamato il principio del minimo tecnicamente possibile"]),
  ("Quali misure proponi subito?",6,"Taglio ad acqua su tutte le macchine; aspirazione localizzata sulla lucidatura; pulizia a umido o con aspiratori di classe H, mai a secco; separazione delle aree; protezione respiratoria adeguata nelle fasi critiche; registro degli esposti e sorveglianza sanitaria.",["Ho previsto lavorazioni ad umido","Ho vietato la pulizia a secco","Ho previsto registro e sorveglianza"])],
 "Nel laboratorio imposti la strategia di misura della silice cristallina in un laboratorio del marmo. Definisci i gruppi e il campionamento, interpreta le misure e proponi le misure immediate, poi confronta ogni risposta con la soluzione di riferimento.","UNI EN 689 · Allegati XLII e XLIII D.lgs. 81/2008")])
E(C,'M2-Z11','Valori limite e misurazioni dell’esposizione',[ES("Esempio guidato · Da ppm a mg/m³ per l’acetone","Verifica di un valore limite.",[
 ["Il dato","Valore limite dell’acetone: 500 ppm.","500 ppm"],["La massa molare","Acetone: 58,08 g/mol.","M = 58,08"],
 ["Il calcolo","mg/m³ = 500 × 58,08 / 24,06.","≈ 1.207 mg/m³"],["Il confronto","L’Allegato XXXVIII riporta 1.210 mg/m³: la differenza dipende dagli arrotondamenti.","≈ 1.210 mg/m³"],
 ["L’uso pratico","Una misura di 300 mg/m³ corrisponde a circa 124 ppm, cioè circa un quarto del limite.","300 mg/m³ ≈ 124 ppm"]],
 "Convertiamo il valore limite dell’acetone. Cinquecento ppm per una massa molare di cinquantotto virgola zero otto, diviso ventiquattro virgola zero sei, fanno circa milleduecentosette milligrammi per metro cubo, in linea con i milleduecentodieci dell’Allegato. Una misura di trecento milligrammi per metro cubo corrisponde a circa centoventiquattro ppm, circa un quarto del limite.","Allegato XXXVIII D.lgs. 81/2008")])
E(C,'M3-Z08','DPI per il rischio chimico',[ES("Esempio guidato · Leggere la marcatura di un guanto chimico","La UNI EN ISO 374-1 e il tempo di permeazione.",[
 ["La marcatura","Il guanto riporta il tipo e le lettere dei prodotti di prova.","Tipo A, B o C"],
 ["Il livello","Il livello di prestazione dipende dal tempo di permeazione: livello 2 oltre 30 minuti, livello 6 oltre 480 minuti.","2 → >30 min · 6 → >480 min"],
 ["I tipi","Tipo A: almeno 6 prodotti con livello 2; tipo B: almeno 3; tipo C: almeno 1 prodotto con livello 1, oltre 10 minuti.","A · B · C"],
 ["La scelta","Si confronta il prodotto usato con quelli di prova e con le indicazioni della sezione 8 della scheda.","Guanto adatto al prodotto"],
 ["L’uso","Il guanto si sostituisce prima del tempo di permeazione e subito se danneggiato o contaminato all’interno.","Sostituzione programmata"]],
 "Leggiamo la marcatura di un guanto chimico. Il tipo, A, B o C, indica quanti prodotti di prova supera e a quale livello. Il livello dipende dal tempo di permeazione: il livello due supera i trenta minuti, il livello sei i quattrocentottanta. Il guanto si sceglie confrontando il prodotto usato con la sezione otto della scheda, e si sostituisce prima del tempo di permeazione.","UNI EN ISO 374-1")])
E(C,'M3-Z09','Sorveglianza sanitaria ed esposizione a cancerogeni',[SC("Il lavaocchi chiuso nel magazzino","Durante un sopralluogo trovi il lavaocchi del reparto acidi dietro una scaffalatura, con la valvola bloccata. Gli addetti dicono che nessuno l’ha mai usato.",[
 ("Che cosa fai subito?",[["Liberi l’accesso, verifichi il funzionamento e segnali il guasto per la riparazione immediata",True,"Corretto: un presidio di emergenza deve essere sempre accessibile e funzionante."],["Nulla, tanto non si usa",False,"Serve proprio quando accade l’incidente."],["Lo togli per fare spazio",False,"È un presidio obbligatorio in caso di rischio di schizzi."]]),
 ("Come eviti che si ripeta?",[["Controlli periodici registrati e segnaletica",True,"Corretto: la verifica periodica mantiene l’efficienza."],["Una circolare una tantum",False,"Non basta."],["Un nuovo lavaocchi in ufficio",False,"Deve essere vicino al punto di rischio."]]),
 ("Un addetto riceve uno schizzo di acido negli occhi. Che cosa si fa?",[["Lavaggio immediato e prolungato con acqua, poi soccorso sanitario con la scheda di sicurezza",True,"Corretto: il lavaggio immediato riduce il danno."],["Si aspetta il medico",False,"Ogni secondo conta."],["Si neutralizza con una base",False,"È pericoloso."]])],
 "Presidi di emergenza accessibili e verificati, lavaggio immediato e soccorso con la scheda di sicurezza: le procedure dell’art. 226 funzionano solo se preparate prima.","Un lavaocchi inutilizzabile nel reparto acidi. Intervieni.","Art. 226 D.lgs. 81/2008")])
